def transform(grid):
    h, w = len(grid), len(grid[0])
    uniform_rows = {r: grid[r][0] for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])}
    uniform_cols = {c: grid[0][c] for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))}
    counts = Counter(list(uniform_rows.values()) + list(uniform_cols.values()))
    if not counts:
        return [row[:] for row in grid]
    wall = counts.most_common(1)[0][0]
    r_walls = [r for r, v in uniform_rows.items() if v == wall]
    c_walls = [c for c, v in uniform_cols.items() if v == wall]
    def intervals(length, walls):
        out, start = [], 0
        for cut in walls:
            if cut > start:
                out.append((start, cut))
            start = cut + 1
        if start < length:
            out.append((start, length))
        return out
    rs, cs = intervals(h, r_walls), intervals(w, c_walls)
    out = [row[:] for row in grid]
    for ri in range(len(rs) - 1):
        r0, r1 = rs[ri], rs[ri + 1]
        if r0[1] - r0[0] != r1[1] - r1[0]:
            continue
        for ci in range(len(cs) - 1):
            c0, c1 = cs[ci], cs[ci + 1]
            if c0[1] - c0[0] != c1[1] - c1[0]:
                continue
            cells = [(ri,ci),(ri,ci+1),(ri+1,ci),(ri+1,ci+1)]
            colors = set()
            patterns = {}
            for rr,cc in cells:
                a,b=rs[rr]; x,y=cs[cc]
                pat={ (r-a,c-x) for r in range(a,b) for c in range(x,y) if grid[r][c] not in (0,wall) }
                patterns[(rr,cc)] = pat
                colors.update(grid[r][c] for r in range(a,b) for c in range(x,y) if grid[r][c] not in (0,wall))
            for color in colors:
                original={key:{p for p in pat if grid[rs[key[0]][0]+p[0]][cs[key[1]][0]+p[1]]==color} for key,pat in patterns.items()}
                for source in cells:
                    base=original[source]
                    if len(base)<3:
                        continue
                    expected={}
                    sr,sc=source
                    for target in cells:
                        tr,tc=target
                        hh=rs[tr][1]-rs[tr][0]; ww=cs[tc][1]-cs[tc][0]
                        expected[target]={(hh-1-r if tr!=sr else r, ww-1-c if tc!=sc else c) for r,c in base}
                    if any(not original[key].issubset(expected[key]) for key in cells):
                        continue
                    exact=sum(bool(original[key]) and original[key]==expected[key] for key in cells)
                    if exact < 2:
                        continue
                    for (rr,cc), pts in expected.items():
                        a,b=rs[rr]; x,y=cs[cc]
                        for r,c in pts:
                            gr,gc=a+r,x+c
                            if out[gr][gc]==0:
                                out[gr][gc]=color
    return out

